/**
 * Send `POST` request to the server.
 */
post() {
  const action = () => {
    this._nextAction = this._actionHandlePost;
    this._sendCommand("POST");
  };
  this._currentAction = action;
  if (this._server.pushAuth && !this._authenticated) {
    this._actionAuthUser();
  } else {
    action();
  }
}
